select distinct temp.FINPROD_ID, temp.BRANCH, temp.P_FINPROD_ID, temp.REVEAL_FILE_ID, temp.FILE_TYPE, temp.SALE_DEPARTMENT, temp.FINPROD_MARKET_ID, temp.FINPROD_NAME, temp.VDATE, temp.MDATE, temp.PORTFOLIO_ID from (select distinct A.FINPROD_ID as FINPROD_ID, C.BRANCH as BRANCH, A.FINPROD_ID as P_FINPROD_ID, D.REVEAL_FILE_ID, D.FILE_TYPE, E.SALE_DEPARTMENT, A.FINPROD_MARKET_ID as FINPROD_MARKET_ID, A.FINPROD_NAME as FINPROD_NAME, A.VDATE as VDATE, A.MDATE as MDATE, B.PORTFOLIO_ID as PORTFOLIO_ID from FIN_PRODUCT A left join PRD_FILE D on D.FINPROD_ID = A.FINPROD_ID left join FIN_PRODUCT_ADD E on E.FINPROD_ID = A.FINPROD_ID, PTL_MANAGE_OBJ B, TRD_PRODUCT_DEAL C where A.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR} AND A.PROFIT_TYPE = #{porfitType,jdbcType=VARCHAR} AND A.P_FINPROD_ID IS NULL AND A.VDATE <= #{sysDate,jdbcType=DATE} AND A.FINPROD_ID = B.MANAGE_OBJ_ID AND A.FINPROD_ID = C.FINPROD_ID AND C.BRANCH != #{noBranchNoValue,jdbcType=DECIMAL} AND C.PS = #{ps,jdbcType=VARCHAR} AND C.TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR} AND (C.IS_CANCEL IS NULL OR C.IS_CANCEL = #{no,jdbcType=VARCHAR}) union all select distinct A.FINPROD_ID as FINPROD_ID, A.BRANCH as BRANCH, A.FINPROD_ID as FINPROD_ID, D.REVEAL_FILE_ID, D.FILE_TYPE, E.SALE_DEPARTMENT, C.FINPROD_MARKET_ID as FINPROD_MARKET_ID, C.FINPROD_NAME as FINPROD_NAME, A.VDATE as VDATE, A.MDATE as MDATE, B.PORTFOLIO_ID as PORTFOLIO_ID from FIN_TRADE_PRODUCT A, PTL_MANAGE_OBJ B, FIN_PRODUCT C left join PRD_FILE D on D.FINPROD_ID = C.FINPROD_ID left join FIN_PRODUCT_ADD E on E.FINPROD_ID = C.FINPROD_ID, TRD_PRODUCT_DEAL I where A.VDATE <= #{sysDate,jdbcType=DATE} AND A.FINPROD_ID= C.FINPROD_ID AND C.P_FINPROD_ID IS NULL AND C.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR} AND C.PROFIT_TYPE = #{porfitType,jdbcType=VARCHAR} AND A.FINPROD_ID = B.MANAGE_OBJ_ID AND A.FINPROD_ID= I.FINPROD_ID AND A.BRANCH = I.BRANCH AND I.TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR} AND (I.IS_CANCEL IS NULL OR I.IS_CANCEL = #{no,jdbcType=VARCHAR}) union all select distinct A.FINPROD_ID as FINPROD_ID, A.BRANCH as BRANCH, C.P_FINPROD_ID as P_FINPROD_ID, G.REVEAL_FILE_ID, G.FILE_TYPE, H.SALE_DEPARTMENT, C.FINPROD_MARKET_ID as FINPROD_MARKET_ID, C.FINPROD_NAME as FINPROD_NAME, A.VDATE as VDATE, A.MDATE as MDATE, B.PORTFOLIO_ID as PORTFOLIO_ID from FIN_TRADE_PRODUCT A, PTL_MANAGE_OBJ B, FIN_PRODUCT C left join PRD_FILE G on G.FINPROD_ID = C.P_FINPROD_ID left join FIN_PRODUCT_ADD H on H.FINPROD_ID = C.P_FINPROD_ID, TRD_PRODUCT_DEAL I where A.VDATE <= #{sysDate,jdbcType=DATE} AND A.FINPROD_ID = C.FINPROD_ID AND C.P_FINPROD_ID IN (select E.FINPROD_ID from FIN_PRODUCT E, FIN_PRODUCT_ADD F where E.P_FINPROD_ID IS NULL AND E.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR} AND E.PROFIT_TYPE = #{porfitType,jdbcType=VARCHAR} AND E.FINPROD_ID = F.FINPROD_ID AND F.IS_LAY = #{yes, jdbcType=VARCHAR}) AND C.P_FINPROD_ID = B.MANAGE_OBJ_ID AND A.FINPROD_ID= I.FINPROD_ID AND A.BRANCH = I.BRANCH AND I.TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR} AND (I.IS_CANCEL IS NULL OR I.IS_CANCEL = #{no,jdbcType=VARCHAR}) ) temp
AND temp.PORTFOLIO_ID in
null) OR temp.PORTFOLIO_ID in (
#{item}
AND temp.VDATE <= #{endVDate,jdbcType=DATE}
AND temp.VDATE >= #{startVDate,jdbcType=DATE}
AND temp.MDATE <= #{endMDate,jdbcType=DATE}
AND temp.MDATE >= #{startMDate,jdbcType=DATE}
AND temp.SALE_DEPARTMENT = #{department,jdbcType=VARCHAR}
AND temp.FILE_TYPE = #{fileType,jdbcType=VARCHAR}
